add_action( 'template_redirect', 'perfectpixel_maintenance_mode', 0 );
add_action( 'admin_bar_menu', 'perfectpixel_maintenance_mode_bar', 100 );

function perfectpixel_maintenance_mode_allowed() {
	$cap = trim( '{{maintenance_capability}}' );
	return current_user_can( $cap ? $cap : 'edit_posts' );
}

function perfectpixel_maintenance_mode() {
	if ( perfectpixel_maintenance_mode_allowed() || wp_doing_ajax() || wp_doing_cron() ) {
		return;
	}
	header( 'Retry-After: 3600' );
	nocache_headers();
	wp_die(
		'<h1>' . esc_html( '{{maintenance_title}}' ) . '</h1><p>' . esc_html( '{{maintenance_message}}' ) . '</p>',
		esc_html( '{{maintenance_title}}' ),
		array( 'response' => 503 )
	);
}

function perfectpixel_maintenance_mode_bar( $wp_admin_bar ) {
	if ( perfectpixel_maintenance_mode_allowed() ) {
		$wp_admin_bar->add_node(
			array(
				'id'    => 'perfectpixel-maintenance',
				'title' => '<span style="background:#d63638;color:#fff;padding:0 8px;border-radius:3px">Συντήρηση</span>',
			)
		);
	}
}
